local config = {
  ui_story_31690401_1_dialog_content = "Where are we sending it to, PlayerName?",
  ui_story_31690401_2_dialog_content = "If I'm not wrong, this huge box belongs to <color=#FFB400>Kleken</color>.",
  ui_story_31690401_3_dialog_content = "So we'll just drop it off with the Istvan Gang.",
  ui_story_31690401_4_dialog_content = "How in the world did you figure that out? I can't wrap my head around it.",
  ui_story_31690401_5_dialog_content = "The devilish-looking octopus printed over all the nails sealing the box reeks of Kleken.",
  ui_story_31690401_6_dialog_content = "You probably didn't notice them because the box is too tall.",
  ui_story_31690401_7_dialog_content = "By the way, I've been wondering... why did you come along to help me?",
  ui_story_31690401_8_dialog_content = "Though I have to admit, the box was very much in the way in the cafe.",
  ui_story_31690401_9_dialog_content = "But it could have waited until some strong Aurorians came along, or even Kleken himself to come and get it.",
  ui_story_31690401_10_dialog_content = "No way!",
  ui_story_31690401_11_dialog_content = "The second rule of the Swashbucklers' Way: <color=#FFB400>Never run when someone's in trouble, always help out when you should!</color>",
  ui_story_31690401_12_dialog_content = "And here you are, in need of help, so how could I just turn away?",
  ui_story_31690401_13_dialog_content = "But didn't you want me to treat this \"help\" as a formal job for you?",
  ui_story_31690401_14_dialog_content = "W-Well...",
  ui_story_31690401_15_dialog_content = "Fine, I just wanted to get a job on my own.",
  ui_story_31690401_16_dialog_content = "So in a sense, you're my first client as a swashbuckler!",
  ui_story_31690401_17_dialog_content = "I guess this is where I say, \"I'm honored\"!",
  ui_story_31690401_X17_dialog_content = "Right?",
  ui_story_31690401_18_dialog_content = "Do you think I'm a child?",
  ui_story_31690401_19_dialog_content = "Of course not! It's your insane strength that made me ask for your help.",
  ui_story_31690401_20_dialog_content = "You definitely got this job because of your abilities.",
  ui_story_31690401_21_dialog_content = "Really? You think I'm—no, no!",
  ui_story_31690401_22_dialog_content = "The third rule of the Swashbucklers' Way: <color=#FFB400>Stay composed when others compliment you, do not be cocky!</color>",
  ui_story_31690401_23_dialog_content = "Speaking of which, what're these Swashbucklers' rules? Don't think I've ever heard of them before.",
  ui_story_31690401_24_dialog_content = "Also, why does it start with the second rule? What's the first?",
  ui_story_31690401_25_dialog_content = "I made the rules myself as a constant reminder of how I should behave.",
  ui_story_31690401_26_dialog_content = "Because my greatest aspiration is to become a true swashbuckler.",
  ui_story_31690401_27_dialog_content = "As for the first rule, it's <color=#FFB400>\"Do not conduct yourself in any way that is contradictory to the swashbuckling spirit.\"</color>",
  ui_story_31690401_28_dialog_content = "Hmm, that one seems a little different from the other two rules.",
  ui_story_31690401_29_dialog_content = "Because it's a quote from Allura, my idol.",
  ui_story_31690401_30_dialog_content = "It's also because of her that I want to be an independent, self-sufficient swashbuckler.",
  ui_story_31690401_31_dialog_content = "I'm telling you that only because you're my first client.",
  ui_story_31690401_32_dialog_content = "And lately, I have run into an unprecedented ideological crisis.",
  ui_story_31690401_33_dialog_content = "Unprecedented?",
  ui_story_31690401_34_dialog_content = "Am I not your first client? Doesn't that mean you just got started?",
  ui_story_31690401_35_dialog_content = "I waited for a long, long time to even get a client!",
  ui_story_31690401_36_dialog_content = "Though the crisis I referred to is somewhat related to that.",
  ui_story_31690401_37_dialog_content = "I've always just been getting jobs through the ladies in Umbraton.",
  ui_story_31690401_38_dialog_content = "But they only give me the easy ones.",
  ui_story_31690401_39_dialog_content = "If this keeps up, I, Super Sadie, will never get anywhere on my journey towards my aspiration.",
  ui_story_31690401_40_dialog_content = "I see. But your strength is truly amazing, I must say.",
  ui_story_31690401_41_dialog_content = "Taking advantage of it should get you more jobs.",
  ui_story_31690401_42_dialog_content = "That's what I thought too! But you're the only one willing to contract me so far.",
  ui_story_31690401_43_dialog_content = "To make up for the age gap between my older friends and me, I even...",
  ui_story_31690401_44_dialog_content = "I even forced myself to read comic books for three whole days!",
  ui_story_31690401_45_dialog_content = "(Yeah, she's still a kid...)",
  ui_story_31690401_46_dialog_content = "Let me guess. You got a lot out of that?",
  ui_story_31690401_47_dialog_content = "Absolutely! The protagonist says that you must solve a problem at the source.",
  ui_story_31690401_48_dialog_content = "To me, the source would have to be the meaning of the swashbuckling spirit!",
  ui_story_31690401_49_dialog_content = "I've been mimicking the older girls, but never pondered the reasons behind their actions.",
  ui_story_31690401_50_dialog_content = "Now I understand that the difference between us is that they know the true meaning of the swashbuckling spirit and I don't!",
  ui_story_31690401_51_dialog_content = "And because I don't, I'm not a real swashbuckler.",
  ui_story_31690401_52_dialog_content = "I can't just keep living in their shadows. I must find my own swashbuckling spirit!",
  ui_story_31690401_57_dialog_content = "Your enthusiasm is kinda contagious. So what do you plan to do next?",
  ui_story_31690401_58_dialog_content = "To finish the job without a hitch to prove that you were right to trust me.",
  ui_story_31690401_X58_dialog_content = "Alright, it's time to get moving! Let's go, PlayerName.",
  ui_story_31690401_59_dialog_content = "Why are you stopping, Sadie? Are you tired?",
  ui_story_31690401_60_dialog_content = "We can take a quick breather here.",
  ui_story_31690401_61_dialog_content = "I think I've run into another crisis, PlayerName.",
  ui_story_31690401_62_dialog_content = "See those two sneaky fellows behind the store in that alley over there?",
  ui_story_31690401_63_dialog_content = "Yeah, they seem to be stuffing a sack with some shiny objects.",
  ui_story_31690401_64_dialog_content = "Those are jewels! They're stealing jewels from the store's back room!",
  ui_story_31690401_65_dialog_content = "But I...",
  ui_story_31690401_66_dialog_content = "Didn't you want to be a swashbuckler? Which rule was it again?",
  ui_story_31690401_67_dialog_content = "Right, the second rule!",
  ui_story_31690401_68_dialog_content = "Never run when someone's in trouble, always help out when you should...",
  ui_story_31690401_69_dialog_content = "I would be stopping their crime! If I weren't already doing a job for you right now.",
  ui_story_31690401_70_dialog_content = "Chivalry is paramount, but getting distracted on a job is irresponsible.",
  ui_story_31690401_71_dialog_content = "I don't know what to do, PlayerName!",
  ui_story_31690401_72_option_content = "Chivalry is the manifestation of the swashbuckling spirit.",
  ui_story_31690401_73_dialog_content = "As your client, I fully understand your position and wouldn't call it irresponsible.",
  ui_story_31690401_74_dialog_content = "Not to mention no one else but you could haul such a heavy box, anyway.",
  ui_story_31690401_75_option_content = "Keeping promises is a part of the swashbuckling spirit.",
  ui_story_31690401_76_dialog_content = "But that and upholding justice aren't mutually exclusive.",
  ui_story_31690401_77_dialog_content = "If it were me, I wouldn't stand idly by, either.",
  ui_story_31690401_78_dialog_content = "And there are only two of them. This should be easy for us.",
  ui_story_31690401_79_dialog_content = "Right, Sadie the Swashbuckler shall right all wrongs, for only justice belongs!",
  ui_story_31690401_80_dialog_content = "Why are you holding me back, PlayerName? We gotta act now, or they'll get away!",
  ui_story_31690401_81_dialog_content = "Look at them. They're just standing there, taking the jewels and putting them in the sack.",
  ui_story_31690401_82_dialog_content = "It's obvious that someone's handing them over. We have to reassess the situation.",
  ui_story_31690401_83_dialog_content = "You mean they have accomplices?",
  ui_story_31690401_84_dialog_content = "Hustle, get more stuff out!",
  ui_story_31690401_85_dialog_content = "Do you know how much effort it took me to break the door down?!",
  ui_story_31690401_86_dialog_content = "This isn't enough to split four ways!",
  ui_story_31690401_87_dialog_content = "Quit whining!",
  ui_story_31690401_88_dialog_content = "None of us are going anywhere if the people up front hear us!",
  ui_story_31690401_89_dialog_content = "I'm going in to see what other valuables are there. Wait here.",
  ui_story_31690401_90_dialog_content = "There you go! There's no place for a coward in this line of work!",
  ui_story_31690401_91_dialog_content = "That makes at least 2-on-4. Let's go back to the box and make a plan.",
  ui_story_31690401_92_dialog_content = "Don't panic, Sadie... You can do this, Sadie...",
  ui_story_31690401_93_dialog_content = "No—I've got no idea what to do, PlayerName!",
  ui_story_31690401_94_dialog_content = "Take it easy, Sadie. We're the only ones who can help at the moment.",
  ui_story_31690401_95_dialog_content = "We're outnumbered, so we might not be able to take them in a fight.",
  ui_story_31690401_96_dialog_content = "Let's calm down, put our heads together, and come up with a plan.",
  ui_story_31690401_97_dialog_content = "I got it!",
  ui_story_31690401_98_dialog_content = "If Allura was here, she'd start shooting like bang, bang, bang!",
  ui_story_31690401_X98_dialog_content = "Then she'd knock the weapons and stolen goods from their hands, scaring them away.",
  ui_story_31690401_99_dialog_content = "But we have no guns, and I wouldn't know how to use one, either.",
  ui_story_31690401_100_dialog_content = "So that's not gonna work. Any other ideas?",
  ui_story_31690401_101_dialog_content = "If Genevieve was here, she'd summon her fans with just one word!",
  ui_story_31690401_102_dialog_content = "Four petty thieves wouldn't stand up to the legion of fans she has!",
  ui_story_31690401_103_dialog_content = "But I have no fans.",
  ui_story_31690401_104_dialog_content = "Yeah, that doesn't sound like a feasible idea.",
  ui_story_31690401_105_dialog_content = "If Smokey was here, she'd laugh out loud",
  ui_story_31690401_106_dialog_content = "while dismissing them as punks and then she'd burn them with fire.",
  ui_story_31690401_107_dialog_content = "But I'm nowhere near as powerful as she is.",
  ui_story_31690401_108_dialog_content = "I guess mimicking the squad you call the \"Umbraton ladies\" isn't an option here.",
  ui_story_31690401_109_dialog_content = "Why not handle it your way?",
  ui_story_31690401_110_dialog_content = "Didn't you want to find a swashbuckling spirit of your own?",
  ui_story_31690401_111_dialog_content = "My own swashbuckling spirit...",
  ui_story_31690401_112_dialog_content = "Oh no, they're about to leave!",
  ui_story_31690401_113_dialog_content = "Forget it! I gotta fight. I mean, the Umbraton ladies get hurt all the time too!",
  ui_story_31690401_114_dialog_content = "No swashbuckler would just watch bad guys leave. Come on, Coolster!",
  ui_story_31690401_115_dialog_content = "<color=#e8d9bb>Whack!</color>",
  ui_story_31690401_116_dialog_content = "Yikes! What was that? Scared the bejesus out of me!",
  ui_story_31690401_117_dialog_content = "Fortunately, the thieves missed that, or they'd be gone by now!",
  ui_story_31690401_118_dialog_content = "I can't believe how strong you are...",
  ui_story_31690401_119_dialog_content = "Just putting the bat over your shoulder was enough to pop the nails off a corner of the box.",
  ui_story_31690401_120_dialog_content = "PlayerName! Look, a note fell out of it!",
  ui_story_31690401_121_dialog_content = "Unfortunately, I'm illiterate.",
  ui_story_31690401_122_dialog_content = "Let me see it.",
  ui_story_31690401_123_dialog_content = "Here you go.",
  ui_story_31690401_124_dialog_content = "I wonder what's in the box? Let me climb up and take a look...",
  ui_story_31690401_125_dialog_content = "\"You figured out this box belonged to me from the octopi, right?\"",
  ui_story_31690401_126_dialog_content = "\"A kind Caelestite like you would also send it back to Umbraton, right?\"",
  ui_story_31690401_127_dialog_content = "\"And I figured it'd be opened sooner or later.\"",
  ui_story_31690401_128_dialog_content = "\"In that case, let me leave you with this thank-you note. —Kleken\"",
  ui_story_31690401_129_dialog_content = "Ugh, Kleken! I'll get you for this!",
  ui_story_31690401_130_dialog_content = "I know what to do now, PlayerName! Justice shall prevail under my watch!",
  ui_story_31690401_131_dialog_content = "All the valuables are loaded. This should be enough.",
  ui_story_31690401_132_dialog_content = "Yeah, hehe it's enough for two lifetimes!",
  ui_story_31690401_133_dialog_content = "What're we waiting for, then? Let's get out of here!",
  ui_story_31690401_134_dialog_content = "<color=#e8d9bb>Shoop!</color>",
  ui_story_31690401_135_dialog_content = "Ugh—!",
  ui_story_31690401_136_dialog_content = "<color=#e8d9bb>Shoop!</color>",
  ui_story_31690401_137_dialog_content = "What's wrong, tall guy? Ow!",
  ui_story_31690401_138_dialog_content = "<color=#e8d9bb>Shoop, shoop!</color>",
  ui_story_31690401_139_dialog_content = "Are kids playing baseball behind the warehouse again? They've sent their balls flying in through the windows!",
  ui_story_31690401_140_dialog_content = "And what does it say on them... <color=#FFB400>666</color>? Kids these days!",
  ui_story_31690401_141_dialog_content = "And they're solid metal. If they struck anyone—",
  ui_story_31690401_142_dialog_content = "Heavens! Four people lying here on the ground! I knew it was dangerous!",
  ui_story_31690401_143_dialog_content = "Hold on, these bags they've got here...",
  ui_story_31690401_144_dialog_content = "Aren't these all from my warehouse? Way to go with the balls!",
  ui_story_31690401_145_dialog_content = "As a bonus for completing the job, I'm treating you to a popsicle!",
  ui_story_31690401_146_dialog_content = "Here you go.",
  ui_story_31690401_147_dialog_content = "Also, I'm interested in knowing how you got the idea for subduing the thieves.",
  ui_story_31690401_148_dialog_content = "After I nudged the lid, I noticed there were shiny things reflecting through the crack.",
  ui_story_31690401_149_dialog_content = "I figured there'd be something useful in a box so bulky.",
  ui_story_31690401_150_dialog_content = "I can always trust in my strength if not anything else, y'know.",
  ui_story_31690401_151_dialog_content = "I climbed onto the box and checked out what was inside.",
  ui_story_31690401_152_dialog_content = "It was full of solid metal balls! How lucky for Super Sadie Swashbuckler 666!",
  ui_story_31690401_153_dialog_content = "Kleken's prank actually ended up helping us...",
  ui_story_31690401_154_dialog_content = "I can't even begin to describe what I'm feeling right now.",
  ui_story_31690401_155_dialog_content = "The balls immediately reminded me of the comics I read three days ago.",
  ui_story_31690401_156_dialog_content = "Comics?",
  ui_story_31690401_157_dialog_content = "Yeah. On the surface, the protagonist is a baseball aficionado.",
  ui_story_31690401_158_dialog_content = "But he actually morphs into a fighter when no one's looking and beats up Eclipsites with Lumina baseballs.",
  ui_story_31690401_159_dialog_content = "Even though I found a way this time, I'm not totally satisfied with the result.",
  ui_story_31690401_160_dialog_content = "But I think your idea was great, and hitting the thieves with such precision is no easy feat!",
  ui_story_31690401_161_dialog_content = "If the perfect rating for swashbuckling were ten, I'd give you a twelve!",
  ui_story_31690401_162_dialog_content = "Really? The—",
  ui_story_31690401_163_dialog_content = "Second rule of the Swashbucklers' Way, right? You did a great job today and deserve to pat yourself on the back.",
  ui_story_31690401_164_dialog_content = "I feel like I'm still copying other people and not doing my own stuff, though.",
  ui_story_31690401_165_dialog_content = "But at least you didn't rush headlong into the situation without thinking as your friends would have.",
  ui_story_31690401_166_dialog_content = "Even though you got your inspiration from a comic book, you still came up with an idea most suitable for you.",
  ui_story_31690401_167_dialog_content = "You protected others, as well as yourself. I'd call that your own unique swashbuckling spirit.",
  ui_story_31690401_168_dialog_content = "Thank you, PlayerName. I finally know what a swashbuckling spirit entails now!",
  ui_story_31690401_169_dialog_content = "But I also know I still have a long way to go to becoming a real swashbuckler.",
  ui_story_31690401_170_dialog_content = "But Super Sadie Swashbuckler 666 is not giving up!",
  ui_story_31690401_171_dialog_content = "You'll see me again when I'm a genuine swashbuckler.",
  ui_story_31690401_172_dialog_content = "Oh, I very much look forward to that.",
  ui_story_31690401_173_dialog_content = "I know one day you'll have a swashbuckling spirit of your own."
}
return config
